#!/usr/bin/env python3
"""Vertical Farm Harvest Energy Planning solver (PySCIPOpt)."""
import os
import csv
import json
import sys

from pyscipopt import Model, quicksum

APP = "/app"
DATA = os.path.join(APP, "data")
SUB = os.path.join(APP, "submissions")
SOLUTION_PATH = os.path.join(SUB, "solution.csv")

TOL = 1e-5


def read_csv(path):
    with open(path, "r", newline="") as f:
        return list(csv.DictReader(f))


def main():
    os.makedirs(SUB, exist_ok=True)

    with open(os.path.join(DATA, "config.json"), "r") as f:
        cfg = json.load(f)
    tol = float(cfg.get("feasibility_tolerance", 1e-5))

    days_rows = read_csv(os.path.join(DATA, "days.csv"))
    rooms_rows = read_csv(os.path.join(DATA, "rooms.csv"))
    lots_rows = read_csv(os.path.join(DATA, "crop_lots.csv"))
    options_rows = read_csv(os.path.join(DATA, "harvest_options.csv"))
    demand_rows = read_csv(os.path.join(DATA, "crop_day_demand.csv"))

    # Days
    day_order = []
    energy_price = {}
    energy_limit = {}
    labor_limit = {}
    cooler_cap = {}
    for r in days_rows:
        d = r["day"]
        day_order.append(d)
        energy_price[d] = float(r["energy_price_per_kwh"])
        energy_limit[d] = float(r["led_energy_limit_kwh"])
        labor_limit[d] = float(r["harvest_labor_hours"])
        cooler_cap[d] = float(r["cooler_capacity_kg"])

    # Rooms
    room_cap = {}
    for r in rooms_rows:
        room_cap[r["room_id"]] = float(r["max_trays_harvested_per_day"])

    # Lots
    lot_crop = {}
    lot_room = {}
    lot_trays = {}
    for r in lots_rows:
        lot = r["lot_id"]
        lot_crop[lot] = r["crop"]
        lot_room[lot] = r["room_id"]
        lot_trays[lot] = float(r["trays_available"])

    # Options
    opt_yield = {}
    opt_energy = {}
    opt_labor = {}
    opt_quality = {}
    options = []  # list of (lot, day)
    for r in options_rows:
        lot, d = r["lot_id"], r["day"]
        if lot not in lot_crop:
            continue
        opt_yield[(lot, d)] = float(r["yield_kg_per_tray"])
        opt_energy[(lot, d)] = float(r["energy_kwh_per_tray"])
        opt_labor[(lot, d)] = float(r["labor_hours_per_tray"])
        opt_quality[(lot, d)] = float(r["quality_penalty_per_tray"])
        options.append((lot, d))

    # Demand
    demand = {}
    min_service = {}
    shortage_pen = {}
    crop_days = []  # list of (crop, day)
    for r in demand_rows:
        c, d = r["crop"], r["day"]
        demand[(c, d)] = float(r["demand_kg"])
        min_service[(c, d)] = float(r["minimum_service_rate"])
        shortage_pen[(c, d)] = float(r["shortage_penalty_per_kg"])
        crop_days.append((c, d))

    # Objective coefficients for x: energy_price[d]*energy + quality
    x_obj = {}
    for (lot, d) in options:
        x_obj[(lot, d)] = energy_price[d] * opt_energy[(lot, d)] + opt_quality[(lot, d)]

    model = Model("vertical_farm_harvest_energy_planning")
    model.hideOutput()

    time_limit = 300.0
    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None:
        try:
            time_limit = min(time_limit, float(env_limit))
        except ValueError:
            pass
    model.setParam("gaprel", 0.0005)
    model.setParam("limits/time", time_limit)

    x = {}
    for (lot, d) in options:
        x[(lot, d)] = model.addVar(
            name=f"x_{lot}_{d}", vtype="C", lb=0.0, ub=lot_trays[lot], obj=x_obj[(lot, d)]
        )

    s = {}
    for (c, d) in crop_days:
        # shortage upper bound: (1 - min_service_rate) * demand
        ub = max(0.0, (1.0 - min_service[(c, d)]) * demand[(c, d)])
        s[(c, d)] = model.addVar(
            name=f"s_{c}_{d}", vtype="C", lb=0.0, ub=ub, obj=shortage_pen[(c, d)]
        )

    # Objective: build explicitly from stored coefficients
    obj_expr = quicksum([x_obj[(lot, d)] * x[(lot, d)] for (lot, d) in options])
    obj_expr += quicksum([shortage_pen[(c, d)] * s[(c, d)] for (c, d) in crop_days])
    model.setObjective(obj_expr, sense="minimize")

    # Lot availability constraints
    for lot in lot_trays:
        terms = [x[(lot, d)] for (l2, d) in options if l2 == lot]
        if terms:
            model.addCons(quicksum(terms) <= lot_trays[lot], name=f"lot_{lot}")

    # Room daily throughput
    for d in day_order:
        for room in room_cap:
            terms = [x[(lot, d)] for (lot, dd) in options if dd == d and lot_room.get(lot) == room]
            if terms:
                model.addCons(quicksum(terms) <= room_cap[room], name=f"room_{room}_{d}")

    # Daily energy
    for d in day_order:
        terms = [opt_energy[(lot, d)] * x[(lot, d)] for (lot, dd) in options if dd == d]
        if terms:
            model.addCons(quicksum(terms) <= energy_limit[d], name=f"energy_{d}")

    # Daily labor
    for d in day_order:
        terms = [opt_labor[(lot, d)] * x[(lot, d)] for (lot, dd) in options if dd == d]
        if terms:
            model.addCons(quicksum(terms) <= labor_limit[d], name=f"labor_{d}")

    # Daily cooler
    for d in day_order:
        terms = [opt_yield[(lot, d)] * x[(lot, d)] for (lot, dd) in options if dd == d]
        if terms:
            model.addCons(quicksum(terms) <= cooler_cap[d], name=f"cooler_{d}")

    # Demand balance + service (balance already enforces shortage = demand - harvest_kg;
    # service bound enforced via shortage variable upper bound)
    for (c, d) in crop_days:
        terms = [opt_yield[(lot, d)] * x[(lot, d)] for (lot, dd) in options if dd == d and lot_crop.get(lot) == c]
        lhs = quicksum(terms) + s[(c, d)]
        model.addCons(lhs == demand[(c, d)], name=f"demand_{c}_{d}")

    model.optimize()

    status = model.getStatus()
    print(f"Solver status: {status}")
    nsols = model.getNSols()
    print(f"Number of solutions: {nsols}")
    best = model.getBestSol()
    obj_val = None
    if best is not None:
        obj_val = model.getObjVal()
        print(f"Objective (total cost): {obj_val:.8f}")

    # Extract solution
    harvest_vals = {}
    shortage_vals = {}
    if best is not None:
        for (lot, d) in options:
            v = model.getVal(x[(lot, d)])
            if v > 1e-9:
                harvest_vals[(lot, d)] = v
        for (c, d) in crop_days:
            v = model.getVal(s[(c, d)])
            if v > 1e-9:
                shortage_vals[(c, d)] = v

    # Validation
    print("=== Validation ===")
    ok = True

    # Lot totals
    for lot in lot_trays:
        tot = sum(harvest_vals.get((lot, d), 0.0) for d in day_order)
        if tot > lot_trays[lot] + tol:
            ok = False
            print(f"VIOLATION lot {lot}: {tot} > {lot_trays[lot]}")

    # Room/day
    for d in day_order:
        for room in room_cap:
            tot = sum(
                harvest_vals.get((lot, d), 0.0)
                for (lot, dd) in options if dd == d and lot_room.get(lot) == room
            )
            if tot > room_cap[room] + tol:
                ok = False
                print(f"VIOLATION room {room} day {d}: {tot} > {room_cap[room]}")

    # Day energy/labor/cooler
    for d in day_order:
        e = sum(opt_energy[(lot, d)] * harvest_vals.get((lot, d), 0.0) for (lot, dd) in options if dd == d)
        h = sum(opt_labor[(lot, d)] * harvest_vals.get((lot, d), 0.0) for (lot, dd) in options if dd == d)
        kg = sum(opt_yield[(lot, d)] * harvest_vals.get((lot, d), 0.0) for (lot, dd) in options if dd == d)
        if e > energy_limit[d] + tol:
            ok = False
            print(f"VIOLATION energy day {d}: {e} > {energy_limit[d]}")
        if h > labor_limit[d] + tol:
            ok = False
            print(f"VIOLATION labor day {d}: {h} > {labor_limit[d]}")
        if kg > cooler_cap[d] + tol:
            ok = False
            print(f"VIOLATION cooler day {d}: {kg} > {cooler_cap[d]}")

    # Demand balance + service
    for (c, d) in crop_days:
        kg = sum(opt_yield[(lot, d)] * harvest_vals.get((lot, d), 0.0)
                 for (lot, dd) in options if dd == d and lot_crop.get(lot) == c)
        sv = shortage_vals.get((c, d), 0.0)
        if abs(kg + sv - demand[(c, d)]) > tol:
            ok = False
            print(f"VIOLATION demand {c} {d}: kg+short={kg + sv} != {demand[(c, d)]}")
        max_short = (1.0 - min_service[(c, d)]) * demand[(c, d)]
        if sv > max_short + tol:
            ok = False
            print(f"VIOLATION service {c} {d}: shortage {sv} > {max_short}")

    # Nonnegativity
    for (lot, d), v in harvest_vals.items():
        if v < -tol:
            ok = False
            print(f"VIOLATION negative harvest {lot} {d}: {v}")
    for (c, d), v in shortage_vals.items():
        if v < -tol:
            ok = False
            print(f"VIOLATION negative shortage {c} {d}: {v}")

    print(f"Validation {'PASSED' if ok else 'FAILED'}")

    # Write solution
    with open(SOLUTION_PATH, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["row_type", "lot_id", "crop", "day", "value"])
        for (lot, d) in options:
            v = harvest_vals.get((lot, d), 0.0)
            if v > 1e-9:
                w.writerow(["harvest", lot, lot_crop[lot], d, f"{v:.8f}"])
        for (c, d) in crop_days:
            v = shortage_vals.get((c, d), 0.0)
            if v > 1e-9:
                w.writerow(["shortage", "", c, d, f"{v:.8f}"])

    print(f"Wrote {SOLUTION_PATH}")

    try:
        model.free()
    except Exception:
        pass


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        import traceback
        traceback.print_exc()
        print(f"Solver error: {e}")
        # best-effort: write header-only solution if missing
        if not os.path.exists(SOLUTION_PATH):
            with open(SOLUTION_PATH, "w", newline="") as f:
                w = csv.writer(f)
                w.writerow(["row_type", "lot_id", "crop", "day", "value"])
        sys.exit(1)
